          <div className="relative bg-[#060010] rounded-2xl border border-white/5 shadow-2xl overflow-hidden">
            <AnimatedList
              items={items}
              onItemSelect={(item, index) => {
                console.log('Selected:', item, index);
                setLastSelected(item);
              }}
