import React from 'react';
import { Check, Plus } from 'lucide-react';
import { cn } from './utils';

interface PricingFeature {
  label: string;
  included: boolean;
  isAddOn?: boolean;
}

interface PricingSectionProps {
  className?: string;
  heading?: string;
  subheading?: string;
  price?: string;
  feeLabel?: string;
